# app.R
# Autographer Annotator - SHINYLIVE VERSION
#
# Runs entirely inside the participant's browser via shinylive
# (WebAssembly R). Nothing is uploaded to any backend, nothing leaves the
# participant's machine, and no R or RStudio installation is required on
# their end.
#
# The camera folder is opened with the browser's File System Access API
# (Chrome / Edge only), with read-write permission. This lets the app:
#   - show the photos straight from the camera (they are never copied into R
#     or onto the computer),
#   - save the results CSV files onto the camera, in a separate results folder,
#   - delete the photos from the camera, and check that none are left.
# Only JPG/JPEG files are ever deleted. The results folder is always skipped.
#
# See DEPLOY_NOTES.txt (kept as a separate file, not this one) for export
# and hosting instructions - deliberately not written here as R code text,
# so automated dependency scanners do not misread it as a package the app
# itself uses.

library(shiny)
library(shinyjs)

# Name of the folder (inside the selected camera folder) where results are
# saved. The delete and check functions never look inside this folder.
RESULTS_FOLDER <- "DAYLIGHT_results"

`%||%` <- function(x, y) {
  if (is.null(x) || length(x) == 0L || is.na(x[1])) y else x
}

# Parses the Autographer timestamp out of a FILENAME.
parse_autographer_time <- function(name) {
  hit <- regmatches(
    name,
    regexpr("[0-9]{8}_[0-9]{6}", name, perl = TRUE)
  )

  if (length(hit) == 1L && nzchar(hit)) {
    parsed <- as.POSIXct(
      hit,
      format = "%Y%m%d_%H%M%S",
      tz = "UTC"
    )
    if (!is.na(parsed)) return(parsed)
  }

  as.POSIXct(NA)
}

safe_minutes <- function(start_time, end_time) {
  if (is.na(start_time) || is.na(end_time)) return(NA_real_)
  max(0, as.numeric(difftime(end_time, start_time, units = "mins")))
}

# Turns a data frame into CSV text (so it can be written by the browser).
csv_text <- function(df) {
  tc <- textConnection(NULL, "w")
  on.exit(close(tc))
  write.csv(df, tc, row.names = FALSE, na = "")
  paste(textConnectionValue(tc), collapse = "\n")
}

# ---------------------------------------------------------------------------
# Browser-side code: opening the camera folder, showing photos, saving
# results, deleting photos and checking for photos.
# ---------------------------------------------------------------------------
camera_js <- sprintf("
window.AG = { dir: null, files: {}, url: null, RESULTS: '%s' };

function agIsImage(name) { return /\\.(jpe?g)$/i.test(name); }

function agSend(id, value) {
  value.stamp = Date.now();
  Shiny.setInputValue(id, value, {priority: 'event'});
}

// Lists every JPG under a folder, skipping the results folder.
async function agWalk(dir, prefix, out) {
  for await (const [name, handle] of dir.entries()) {
    if (handle.kind === 'directory') {
      if (name === AG.RESULTS) continue;
      await agWalk(handle, prefix + name + '/', out);
    } else if (agIsImage(name)) {
      out.push({ path: prefix + name, name: name, handle: handle });
    }
  }
  return out;
}

// Opens the folder picker. Must be called straight from a click.
async function agPick() {
  if (!window.showDirectoryPicker) {
    agSend('ag_error', { message: 'This browser cannot open the camera. Please use Google Chrome or Microsoft Edge on a laptop or desktop computer.' });
    return false;
  }
  try {
    AG.dir = await window.showDirectoryPicker({ id: 'autographer', mode: 'readwrite' });
    return true;
  } catch (e) {
    if (e && e.name === 'AbortError') return false;
    agSend('ag_error', { message: 'Could not open the folder: ' + (e.message || e) });
    return false;
  }
}

async function agLoad() {
  if (!(await agPick())) return;
  agSend('ag_busy', { message: 'Reading the camera folder...' });
  try {
    const list = await agWalk(AG.dir, '', []);
    AG.files = {};
    list.forEach(function(f) { AG.files[f.path] = f.handle; });
    agSend('ag_files', {
      folder: AG.dir.name,
      path: list.map(function(f) { return f.path; }),
      name: list.map(function(f) { return f.name; })
    });
  } catch (e) {
    agSend('ag_error', { message: 'Could not read the folder: ' + (e.message || e) });
  }
}

async function agCount() {
  const list = await agWalk(AG.dir, '', []);
  return list.length;
}

async function agCheck() {
  if (!AG.dir) { if (!(await agPick())) return; }
  try {
    const n = await agCount();
    agSend('ag_check_result', { ok: true, remaining: n, folder: AG.dir.name });
  } catch (e) {
    agSend('ag_check_result', { ok: false, error: String(e.message || e) });
  }
}

async function agWriteResults(files) {
  const d = await AG.dir.getDirectoryHandle(AG.RESULTS, { create: true });
  for (const f of files) {
    const fh = await d.getFileHandle(f.name, { create: true });
    const w = await fh.createWritable();
    await w.write(f.content);
    await w.close();
  }
}

// Deletes JPGs only, never anything inside the results folder.
async function agDeleteIn(dir, stats) {
  const entries = [];
  for await (const entry of dir.entries()) entries.push(entry);
  for (const [name, handle] of entries) {
    if (handle.kind === 'directory') {
      if (name === AG.RESULTS) continue;
      await agDeleteIn(handle, stats);
    } else if (agIsImage(name)) {
      try { await dir.removeEntry(name); stats.deleted++; }
      catch (e) { stats.failed++; }
    }
  }
}

$(document).on('click', '#ag_pick', function() { agLoad(); });
$(document).on('click', '#check_images', function() { agCheck(); });

$(document).on('shiny:connected', function() {

  Shiny.addCustomMessageHandler('ag_show', async function(m) {
    const img = document.getElementById('ag_img');
    const ph = document.getElementById('ag_placeholder');
    if (!img || !ph) return;
    if (!m.path) {
      img.style.display = 'none';
      img.removeAttribute('src');
      ph.style.display = 'block';
      ph.textContent = m.message || '';
      return;
    }
    const handle = AG.files[m.path];
    if (!handle) return;
    try {
      const file = await handle.getFile();
      const url = URL.createObjectURL(file);
      const old = AG.url;
      AG.url = url;
      img.src = url;
      img.style.display = 'block';
      ph.style.display = 'none';
      if (old) setTimeout(function() { URL.revokeObjectURL(old); }, 1000);
    } catch (e) {
      img.style.display = 'none';
      ph.style.display = 'block';
      ph.textContent = 'Could not read this image.';
    }
  });

  Shiny.addCustomMessageHandler('ag_save', async function(m) {
    try {
      if (!AG.dir) throw new Error('No camera folder has been selected.');
      await agWriteResults(m.files);
      agSend('ag_save_result', { ok: true, n: m.files.length, folder: AG.dir.name + '/' + AG.RESULTS });
    } catch (e) {
      agSend('ag_save_result', { ok: false, error: String(e.message || e) });
    }
  });

  Shiny.addCustomMessageHandler('ag_delete', async function(m) {
    const stats = { deleted: 0, failed: 0 };
    try {
      if (!AG.dir) throw new Error('No camera folder has been selected.');
      // Save the results first. If saving fails, nothing is deleted.
      if (m.files && m.files.length) await agWriteResults(m.files);
      await agDeleteIn(AG.dir, stats);
      AG.files = {};
      const remaining = await agCount();
      agSend('ag_delete_result', { ok: true, deleted: stats.deleted, failed: stats.failed, remaining: remaining });
    } catch (e) {
      agSend('ag_delete_result', { ok: false, deleted: stats.deleted, error: String(e.message || e) });
    }
  });
});
", RESULTS_FOLDER)

