          e.preventDefault();
          Shiny.setInputValue('key_space', Date.now(), {priority: 'event'});
        }
        if (e.code === 'ArrowRight') {
          Shiny.setInputValue('key_next', Date.now(), {priority: 'event'});
        }
        if (e.code === 'ArrowLeft') {
          Shiny.setInputValue('key_previous', Date.now(), {priority: 'event'});
        }
        if (e.key === 'o' || e.key === 'O') {
          Shiny.setInputValue('key_outdoors', Date.now(), {priority: 'event'});
        }
        if (e.key === 'i' || e.key === 'I') {
          Shiny.setInputValue('key_indoors', Date.now(), {priority: 'event'});
        }
        if (e.key === 'u' || e.key === 'U') {
          Shiny.setInputValue('key_undo', Date.now(), {priority: 'event'});
        }
      });

      // 'No' is the default button in the delete confirmation.
      $(document).on('shown.bs.modal', function() {
        $('#confirm_delete_no').trigger('focus');
