  )
)

server <- function(input, output, session) {

  rv <- reactiveValues(
    upload = NULL,                # data.frame: path, name (from the camera folder)
    folder = NULL,                # name of the selected camera folder
    files = character(),          # ordered relative paths on the camera
    display_names = character(),  # ordered original filenames
    times = as.POSIXct(character()),
    index = 1L,
    playing = FALSE,
    active_state = "Indoors",
    labels = character(),
    intervals = data.frame(),
    saved = FALSE,                # results calculated
    saved_to_camera = FALSE       # results written to the camera
  )

  clear_images <- function(message) {
    rv$upload <- NULL
    rv$files <- character()
    rv$display_names <- character()
    rv$times <- as.POSIXct(character())
    rv$index <- 1L
    rv$playing <- FALSE
    rv$labels <- character()
    rv$intervals <- data.frame()
    updateSliderInput(session, "jump_index", min = 1, max = 1, value = 1)
    session$sendCustomMessage("ag_show", list(path = "", message = message))
  }

  apply_ordering <- function() {
    req(rv$upload)

    df <- rv$upload

    if (nrow(df) == 0L) {
      clear_images("No photos were found in this folder.")
      showNotification("No JPG images were found in that folder.", type = "error")
      return()
    }

    times <- as.POSIXct(
      vapply(df$name, parse_autographer_time, as.POSIXct(NA)),
      origin = "1970-01-01",
      tz = "UTC"
    )

    ord <- switch(
      input$ordering,
      filename = order(basename(df$name)),
      uploadorder = seq_len(nrow(df)),
      timestamp = order(is.na(times), times, basename(df$name)),
      order(is.na(times), times, basename(df$name))
    )

    rv$files <- df$path[ord]
    rv$display_names <- df$name[ord]
    rv$times <- times[ord]
    rv$index <- 1L
    rv$playing <- FALSE
    rv$active_state <- "Indoors"
    rv$labels <- rep("Indoors", length(rv$files))
    rv$intervals <- data.frame()
    rv$saved <- FALSE
    rv$saved_to_camera <- FALSE

    updateSliderInput(
      session,
      "jump_index",
      min = 1,
      max = length(rv$files),
      value = 1
    )

    n_missing_time <- sum(is.na(times))
    msg <- paste(length(rv$files), "images loaded.")
    if (n_missing_time > 0L) {
      msg <- paste0(
        msg, " ", n_missing_time,
        " file(s) had no readable timestamp in their filename."
      )
    }
    showNotification(msg, type = "message", duration = 8)
  }

  # ---- Camera folder ------------------------------------------------------

  observeEvent(input$ag_files, {
    x <- input$ag_files
    rv$folder <- x$folder %||% NULL
    rv$upload <- data.frame(
      path = as.character(unlist(x$path)),
      name = as.character(unlist(x$name)),
      stringsAsFactors = FALSE
    )
    apply_ordering()
  })

  observeEvent(input$ag_busy, {
    showNotification(input$ag_busy$message, type = "message", duration = 3)
  })

  observeEvent(input$ag_error, {
    showNotification(input$ag_error$message, type = "error", duration = 12)
  })

  output$folder_name <- renderText({
    if (is.null(rv$folder)) "No folder selected" else paste("Folder:", rv$folder)
  })

  # Show the current photo (read straight from the camera by the browser).
  observe({
    if (length(rv$files) == 0L) return()
    session$sendCustomMessage("ag_show", list(path = rv$files[rv$index]))
  })

  output$viewer_overlay <- renderUI({
    if (length(rv$files) == 0L) return(NULL)

    image_state <- rv$labels[rv$index]
    state_class <- if (identical(image_state, "Outdoors")) {
      "state-banner outdoors"
    } else {
      "state-banner indoors"
    }

    tagList(
      div(class = state_class, toupper(image_state)),
      div(
        class = "image-info",
        paste0(
          "Image ", rv$index, " / ", length(rv$files),
          " | ", rv$display_names[rv$index],
          " | ", format(rv$times[rv$index], "%Y-%m-%d %H:%M:%S", tz = "UTC"),
          " UTC | ", if (rv$playing) "PLAYING" else "PAUSED"
        )
      )
    )
  })

  # ---- Review controls ----------------------------------------------------

  observeEvent(input$reset_review, {
    req(length(rv$files) > 0L)
    rv$index <- 1L
    rv$playing <- FALSE
    rv$active_state <- "Indoors"
    rv$labels <- rep("Indoors", length(rv$files))
    rv$intervals <- data.frame()
    rv$saved <- FALSE
    rv$saved_to_camera <- FALSE
    updateSliderInput(session, "jump_index", value = 1)
    showNotification("Review reset. Images were not reloaded.", type = "message")
  })

  observeEvent(input$ordering, {
    if (!is.null(rv$upload) && nrow(rv$upload) > 0L) apply_ordering()
  }, ignoreInit = TRUE)

  observeEvent(input$play_pause, {
    req(length(rv$files) > 0L)
    rv$playing <- !rv$playing
  })

  observeEvent(input$key_space, {
    req(length(rv$files) > 0L)
    rv$playing <- !rv$playing
  })

  observeEvent(input$stop, {
    rv$playing <- FALSE
    rv$index <- 1L
    updateSliderInput(session, "jump_index", value = 1)
  })

  go_next <- function() {
    req(length(rv$files) > 0L)
    rv$playing <- FALSE
    old_index <- rv$index
    rv$index <- min(length(rv$files), rv$index + 1L)
    if (rv$index > old_index) {
      rv$labels[rv$index] <- rv$active_state
      rv$saved <- FALSE
      rv$saved_to_camera <- FALSE
    }
    updateSliderInput(session, "jump_index", value = rv$index)
  }

  go_previous <- function() {
    req(length(rv$files) > 0L)
    rv$playing <- FALSE
    rv$index <- max(1L, rv$index - 1L)
    updateSliderInput(session, "jump_index", value = rv$index)
  }

  observeEvent(input$next_image, go_next())
  observeEvent(input$key_next, go_next())
  observeEvent(input$previous, go_previous())
  observeEvent(input$key_previous, go_previous())

  observeEvent(input$faster, {
    updateSliderInput(session, "fps", value = min(12, input$fps + 0.25))
  })

  observeEvent(input$slower, {
    updateSliderInput(session, "fps", value = max(0.25, input$fps - 0.25))
  })

  observeEvent(input$jump_index, {
    req(length(rv$files) > 0L)
    rv$playing <- FALSE
    new_index <- max(1L, min(length(rv$files), as.integer(input$jump_index)))
    if (new_index > rv$index) {
      rv$labels[(rv$index + 1L):new_index] <- rv$active_state
      rv$saved <- FALSE
      rv$saved_to_camera <- FALSE
    }
    rv$index <- new_index
  }, ignoreInit = TRUE)

  observe({
    req(rv$playing, length(rv$files) > 0L)

    invalidateLater(max(80, round(1000 / input$fps)), session)

    isolate({
      if (rv$index < length(rv$files)) {
        rv$index <- rv$index + 1L
        rv$labels[rv$index] <- rv$active_state
        rv$saved <- FALSE
        rv$saved_to_camera <- FALSE
        updateSliderInput(session, "jump_index", value = rv$index)
      } else {
        rv$playing <- FALSE
        showNotification("End of sequence reached.", type = "message")
      }
    })
  })

  toggle_state <- function() {
    req(length(rv$files) > 0L)

    rv$active_state <- if (identical(rv$active_state, "Indoors")) {
      "Outdoors"
    } else {
      "Indoors"
    }

    rv$labels[rv$index] <- rv$active_state
    rv$saved <- FALSE
    rv$saved_to_camera <- FALSE

    showNotification(
      paste("Active classification:", toupper(rv$active_state)),
      type = "message",
      duration = 3
    )
  }

  observeEvent(input$toggle_outdoors, toggle_state())
  observeEvent(input$toggle_outdoors_right, toggle_state())
  observeEvent(input$key_outdoors, toggle_state())

  observe({
    label <- if (identical(rv$active_state, "Outdoors")) "INDOORS" else "OUTDOORS"

    updateActionButton(session, "toggle_outdoors", label = label)
    updateActionButton(session, "toggle_outdoors_right", label = label)

    runjs(sprintf(
      "$('#toggle_outdoors').removeClass('btn-success btn-secondary').addClass('%s');",
      if (identical(rv$active_state, "Outdoors")) "btn-secondary" else "btn-success"
    ))
    runjs(sprintf(
      "$('#toggle_outdoors_right').removeClass('btn-success btn-secondary').addClass('%s');",
      if (identical(rv$active_state, "Outdoors")) "btn-secondary" else "btn-success"
    ))
  })

  # ---- Results ------------------------------------------------------------

  calculate_results <- function() {
    req(length(rv$files) > 0L)

    labs <- rv$labels
    if (length(labs) != length(rv$files)) {
      labs <- rep("Indoors", length(rv$files))
    }

    starts <- c(1L, which(labs[-1L] != labs[-length(labs)]) + 1L)
    ends <- c(starts[-1L] - 1L, length(labs))

    rv$intervals <- data.frame(
      interval_id = seq_along(starts),
      state = labs[starts],
      start_time = rv$times[starts],
      end_time = rv$times[ends],
      minutes = mapply(
        safe_minutes,
        rv$times[starts],
        rv$times[ends]
      ),
      stringsAsFactors = FALSE
    )

    rv$intervals
  }

  transition_index <- function() {
    c(1L, which(rv$labels[-1L] != rv$labels[-length(rv$labels)]) + 1L)
  }

  intervals_df <- function() {
    x <- calculate_results()
    x$start_time <- format(x$start_time, "%Y-%m-%d %H:%M:%S", tz = "UTC")
    x$end_time <- format(x$end_time, "%Y-%m-%d %H:%M:%S", tz = "UTC")
    x
  }

  markers_df <- function() {
    req(length(rv$files) > 0L)
    transition_idx <- transition_index()
    data.frame(
      event_id = seq_along(transition_idx),
      image_index = transition_idx,
      image_file = rv$display_names[transition_idx],
      time = format(rv$times[transition_idx], "%Y-%m-%d %H:%M:%S", tz = "UTC"),
      new_state = rv$labels[transition_idx],
      stringsAsFactors = FALSE
    )
  }

  totals_df <- function() {
    ints <- calculate_results()
    ok <- !is.na(ints$minutes)
    if (!any(ok)) {
      return(data.frame(state = unique(ints$state), minutes = NA_real_, percent = NA_real_))
    }
    totals <- aggregate(minutes ~ state, ints[ok, , drop = FALSE], sum)
    names(totals) <- c("state", "minutes")
    totals$minutes <- round(totals$minutes, 2)
    total_minutes <- sum(totals$minutes, na.rm = TRUE)
    totals$percent <- if (total_minutes > 0) {
      round(100 * totals$minutes / total_minutes, 1)
    } else {
      NA_real_
    }
    totals
  }

  # The three results files, ready to be written to the camera.
  results_files <- function() {
    stamp <- format(Sys.time(), "%Y%m%d_%H%M%S")
    list(
      list(name = paste0("autographer_intervals_", stamp, ".csv"), content = csv_text(intervals_df())),
      list(name = paste0("autographer_markers_", stamp, ".csv"), content = csv_text(markers_df())),
      list(name = paste0("autographer_totals_", stamp, ".csv"), content = csv_text(totals_df()))
    )
  }

  observeEvent(input$finish, {
    req(length(rv$files) > 0L)
    rv$playing <- FALSE
    calculate_results()
    rv$saved <- TRUE
    session$sendCustomMessage("ag_save", list(files = results_files()))
  })

  observeEvent(input$ag_save_result, {
    r <- input$ag_save_result
    if (isTRUE(r$ok)) {
      rv$saved_to_camera <- TRUE
      showNotification(
        paste0("Review finished. Your results have been saved on the camera (",
               r$folder, ")."),
        type = "message",
        duration = 10
      )
    } else {
      showModal(modalDialog(
        title = "Results not saved",
        p("Your results could not be saved on the camera:"),
        p(code(r$error %||% "unknown error")),
        p("Please use the CSV download buttons at the top of the page, ",
          "or contact the research team."),
        easyClose = TRUE,
        footer = modalButton("OK")
      ))
    }
  })

  output$download_intervals <- downloadHandler(
    filename = function() {
      paste0("autographer_intervals_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      write.csv(intervals_df(), file, row.names = FALSE, na = "")
    }
  )

  output$download_markers <- downloadHandler(
    filename = function() {
      paste0("autographer_markers_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      write.csv(markers_df(), file, row.names = FALSE, na = "")
    }
  )

  output$download_totals <- downloadHandler(
    filename = function() {
      paste0("autographer_totals_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      write.csv(totals_df(), file, row.names = FALSE, na = "")
    }
  )

  # ---- Delete and check ---------------------------------------------------

  observeEvent(input$delete_images, {
    if (is.null(rv$folder)) {
      showModal(modalDialog(
        title = "Select the camera first",
        p("Press ", strong("Select Autographer folder..."),
          " and choose the camera folder, then press ",
          strong("Delete all images from camera"), " again."),
        easyClose = TRUE,
        footer = modalButton("OK")
      ))
      return()
    }

    rv$playing <- FALSE

    showModal(modalDialog(
      title = "Delete all images?",
      p(strong("This will permanently delete all images on the Autographer camera. Are you sure?")),
      if (length(rv$files) > 0L && !isTRUE(rv$saved_to_camera)) {
        p("Your results will be saved on the camera first.")
      },
      p(class = "shortcut",
        paste0("Your results in the ", RESULTS_FOLDER, " folder will not be deleted.")),
      easyClose = TRUE,
      footer = tagList(
        tags$button(
          id = "confirm_delete_no",
          type = "button",
          class = "btn btn-primary",
          `data-dismiss` = "modal",
          `data-bs-dismiss` = "modal",
          autofocus = NA,
          "No"
        ),
        actionButton("confirm_delete_yes", "Yes, delete all images", class = "btn-danger")
      )
    ))
  })

  observeEvent(input$confirm_delete_yes, {
    removeModal()
    files <- if (length(rv$files) > 0L && !isTRUE(rv$saved_to_camera)) {
      calculate_results()
      rv$saved <- TRUE
      results_files()
    } else {
      list()
    }
    showNotification("Deleting images...", id = "deleting", duration = NULL, type = "warning")
    session$sendCustomMessage("ag_delete", list(files = files))
  })

  observeEvent(input$ag_delete_result, {
    removeNotification("deleting")
    r <- input$ag_delete_result

    if (!isTRUE(r$ok)) {
      showModal(modalDialog(
        title = "Images not deleted",
        p("The images could not be deleted:"),
        p(code(r$error %||% "unknown error")),
        p("There are still images on the camera, please repeat the delete ",
          "function or contact the research team"),
        easyClose = TRUE,
        footer = modalButton("OK")
      ))
      return()
    }

    rv$saved_to_camera <- TRUE
    clear_images("The photos have been deleted from the camera.")

    showNotification(
      paste0(r$deleted, " image(s) deleted. Your results were kept. ",
             "Now press 'Check camera for images'."),
      type = "message",
      duration = 12
    )
  })

  observeEvent(input$ag_check_result, {
    r <- input$ag_check_result

    msg <- if (!isTRUE(r$ok)) {
      paste("The camera could not be checked:", r$error %||% "unknown error")
    } else if (identical(as.integer(r$remaining), 0L)) {
      "There are no images on this camera"
    } else {
      "There are still images on the camera, please repeat the delete function or contact the research team"
    }

    showModal(modalDialog(
      title = "Camera check",
      p(strong(msg)),
      easyClose = TRUE,
      footer = modalButton("OK")
    ))
  })

  # ---- Status and tables --------------------------------------------------

  output$progress_ui <- renderUI({
    if (length(rv$files) == 0L) return(NULL)

    pct <- round(100 * rv$index / length(rv$files), 1)

    tagList(
      div(
        class = "progress",
        div(
          class = "progress-bar",
          role = "progressbar",
          style = paste0("width:", pct, "%;"),
          paste0(pct, "%")
        )
      )
    )
  })

  output$status_box <- renderUI({
    if (length(rv$files) == 0L) {
      return(div(class = "status-box", "No images loaded."))
    }

    div(
      class = "status-box",
      HTML(paste0(
        "<b>Images loaded:</b> ", length(rv$files), "<br>",
        "<b>Current image:</b> ", rv$labels[rv$index], "<br>",
        "<b>Active mode:</b> ", rv$active_state, "<br>",
        "<b>Image:</b> ", rv$index, " / ", length(rv$files), "<br>",
        "<b>Results calculated:</b> ", if (rv$saved) "Yes" else "No", "<br>",
        "<b>Results saved on camera:</b> ", if (rv$saved_to_camera) "Yes" else "No"
      ))
    )
  })

  output$event_log <- renderTable({
    req(length(rv$files) > 0L)

    transition_idx <- transition_index()
    x <- data.frame(
      Time = format(rv$times[transition_idx], "%H:%M:%S", tz = "UTC"),
      State = rv$labels[transition_idx],
      Image = transition_idx,
      check.names = FALSE
    )
    x[nrow(x):1, , drop = FALSE]
  }, striped = TRUE, bordered = FALSE, spacing = "xs")

  output$marker_table <- renderTable({
    req(length(rv$files) > 0L)

    transition_idx <- transition_index()

    data.frame(
      Marker = seq_along(transition_idx),
      Image = transition_idx,
      Time = format(rv$times[transition_idx], "%Y-%m-%d %H:%M:%S", tz = "UTC"),
      State = rv$labels[transition_idx],
      File = rv$display_names[transition_idx],
      check.names = FALSE
    )
  }, striped = TRUE, bordered = TRUE, spacing = "s")

  output$interval_table <- renderTable({
    if (length(rv$files) == 0L) {
      return(data.frame(Message = "No images loaded."))
    }

    calculate_results()

    data.frame(
      Interval = rv$intervals$interval_id,
      State = rv$intervals$state,
      Start = format(rv$intervals$start_time, "%Y-%m-%d %H:%M:%S", tz = "UTC"),
      End = format(rv$intervals$end_time, "%Y-%m-%d %H:%M:%S", tz = "UTC"),
      Minutes = round(rv$intervals$minutes, 2),
      check.names = FALSE
    )
  }, striped = TRUE, bordered = TRUE, spacing = "s")

  output$totals_table <- renderTable({
    if (length(rv$files) == 0L) {
      return(data.frame(Message = "No images loaded."))
    }

    totals <- totals_df()
    names(totals) <- c("State", "Minutes", "Percent")
    totals
  }, striped = TRUE, bordered = TRUE, spacing = "s")

  observeEvent(input$exit_app, {
    rv$playing <- FALSE
    stopApp()
  })
}

