server <- function(input, output, session) {

  rv <- reactiveValues(
    folder = NULL,
    files = character(),
    times = as.POSIXct(character()),
    index = 1L,
    playing = FALSE,
    active_state = "Indoors",
    labels = character(),
    intervals = data.frame(),
    results_dir = NULL,
    saved = FALSE,
    source_seed_name = NULL
  )

  load_folder <- function(folder) {
    if (is.null(folder) || !dir.exists(folder)) {
      showNotification("A valid JPG folder could not be opened.", type = "error")
      return()
    }

    files <- list.files(
      folder,
      pattern = "\\.(jpg|jpeg)$",
      full.names = TRUE,
      ignore.case = TRUE
    )

    if (length(files) == 0L) {
      showNotification("No JPG images were found in that folder.", type = "error")
      return()
    }

    times <- as.POSIXct(
      vapply(files, parse_autographer_time, as.POSIXct(NA)),
      origin = "1970-01-01",
      tz = "UTC"
    )

    ord <- switch(
      input$ordering,
      filename = order(basename(files)),
      mtime = order(file.info(files)$mtime, basename(files)),
      timestamp = order(times, basename(files)),
      order(times, basename(files))
    )

    rv$folder <- normalizePath(folder)
    rv$files <- files[ord]
    rv$times <- times[ord]
    rv$index <- 1L
    rv$playing <- FALSE
    rv$active_state <- "Indoors"
    rv$labels <- rep("Indoors", length(rv$files))
    rv$intervals <- data.frame()
    rv$results_dir <- file.path(rv$folder, "Autographer_review_results")
    rv$saved <- FALSE

    updateSliderInput(
      session,
      "jump_index",
      min = 1,
      max = length(rv$files),
      value = 1
    )

    showNotification(
      paste(length(rv$files), "images loaded from", rv$folder),
      type = "message",
      duration = 8
    )
  }

  observeEvent(input$open_jpg, {
    chosen <- tryCatch(
      file.choose(),
      error = function(e) NULL
    )

    if (is.null(chosen) || !file.exists(chosen)) {
      showNotification("No JPG was selected.", type = "warning")
      return()
    }

    if (!grepl("\\.(jpg|jpeg)$", chosen, ignore.case = TRUE)) {
      showNotification("Please select a JPG image.", type = "error")
      return()
    }

    load_folder(dirname(normalizePath(chosen)))
  })

  observeEvent(input$reload, {
    req(rv$folder)
    load_folder(rv$folder)
  })

  observeEvent(input$ordering, {
    if (!is.null(rv$folder) && dir.exists(rv$folder)) {
      load_folder(rv$folder)
    }
  }, ignoreInit = TRUE)

  observeEvent(input$play_pause, {
    req(length(rv$files) > 0L)
    rv$playing <- !rv$playing
  })

  observeEvent(input$key_space, {
    req(length(rv$files) > 0L)
    rv$playing <- !rv$playing
  })

  observeEvent(input$stop, {
    rv$playing <- FALSE
    rv$index <- 1L
    updateSliderInput(session, "jump_index", value = 1)
  })

  go_next <- function() {
    req(length(rv$files) > 0L)
    rv$playing <- FALSE
    old_index <- rv$index
    rv$index <- min(length(rv$files), rv$index + 1L)
    if (rv$index > old_index) {
      rv$labels[rv$index] <- rv$active_state
      rv$saved <- FALSE
    }
    updateSliderInput(session, "jump_index", value = rv$index)
  }

  go_previous <- function() {
    req(length(rv$files) > 0L)
    rv$playing <- FALSE
    rv$index <- max(1L, rv$index - 1L)
    updateSliderInput(session, "jump_index", value = rv$index)
  }

  observeEvent(input$next_image, go_next())
  observeEvent(input$key_next, go_next())
  observeEvent(input$previous, go_previous())
  observeEvent(input$key_previous, go_previous())

  observeEvent(input$faster, {
    updateSliderInput(session, "fps", value = min(12, input$fps + 0.25))
  })

  observeEvent(input$slower, {
    updateSliderInput(session, "fps", value = max(0.25, input$fps - 0.25))
  })

  observeEvent(input$jump_index, {
    req(length(rv$files) > 0L)
    rv$playing <- FALSE
    new_index <- max(1L, min(length(rv$files), as.integer(input$jump_index)))
    if (new_index > rv$index) {
      rv$labels[(rv$index + 1L):new_index] <- rv$active_state
      rv$saved <- FALSE
    }
    rv$index <- new_index
  }, ignoreInit = TRUE)

  observe({
    req(rv$playing, length(rv$files) > 0L)

    invalidateLater(max(80, round(1000 / input$fps)), session)

    if (rv$index < length(rv$files)) {
      rv$index <- rv$index + 1L
      rv$labels[rv$index] <- rv$active_state
      rv$saved <- FALSE
      updateSliderInput(session, "jump_index", value = rv$index)
    } else {
      rv$playing <- FALSE
      showNotification("End of sequence reached.", type = "message")
    }
  })

  toggle_state <- function() {
    req(length(rv$files) > 0L)

    rv$active_state <- if (identical(rv$active_state, "Indoors")) {
      "Outdoors"
    } else {
      "Indoors"
    }

    # Pressing the button explicitly overrides the current image.
    rv$labels[rv$index] <- rv$active_state
    rv$saved <- FALSE

    showNotification(
      paste("Active classification:", toupper(rv$active_state)),
      type = "message",
      duration = 3
    )
  }

  observeEvent(input$toggle_outdoors, toggle_state())
  observeEvent(input$toggle_outdoors_right, toggle_state())
  observeEvent(input$key_outdoors, toggle_state())

  observe({
    label <- if (identical(rv$active_state, "Outdoors")) "INDOORS" else "OUTDOORS"
    class_name <- if (identical(rv$active_state, "Outdoors")) {
      "btn-secondary big-action"
    } else {
      "btn-success big-action"
    }

    updateActionButton(session, "toggle_outdoors", label = label)
    updateActionButton(session, "toggle_outdoors_right", label = label)

    runjs(sprintf(
      "$('#toggle_outdoors').removeClass('btn-success btn-secondary').addClass('%s');",
      if (identical(rv$active_state, "Outdoors")) "btn-secondary" else "btn-success"
    ))
    runjs(sprintf(
      "$('#toggle_outdoors_right').removeClass('btn-success btn-secondary').addClass('%s');",
      if (identical(rv$active_state, "Outdoors")) "btn-secondary" else "btn-success"
    ))
  })

  calculate_results <- function() {
    req(length(rv$files) > 0L)

    labs <- rv$labels
    if (length(labs) != length(rv$files)) {
      labs <- rep("Indoors", length(rv$files))
    }

    starts <- c(1L, which(labs[-1L] != labs[-length(labs)]) + 1L)
    ends <- c(starts[-1L] - 1L, length(labs))

    rv$intervals <- data.frame(
      interval_id = seq_along(starts),
      state = labs[starts],
      start_time = rv$times[starts],
      end_time = rv$times[ends],
      minutes = mapply(
        safe_minutes,
        rv$times[starts],
        rv$times[ends]
      ),
      stringsAsFactors = FALSE
    )

    rv$intervals
  }

  save_results <- function() {
    calculate_results()

    dir.create(rv$results_dir, recursive = TRUE, showWarnings = FALSE)
    stamp <- format(Sys.time(), "%Y%m%d_%H%M%S")

    intervals <- rv$intervals
    intervals$start_time <- format(intervals$start_time, "%Y-%m-%d %H:%M:%S", tz = "UTC")
    intervals$end_time <- format(intervals$end_time, "%Y-%m-%d %H:%M:%S", tz = "UTC")

    transition_idx <- c(1L, which(rv$labels[-1L] != rv$labels[-length(rv$labels)]) + 1L)
    markers <- data.frame(
      event_id = seq_along(transition_idx),
      image_index = transition_idx,
      image_file = basename(rv$files[transition_idx]),
      time = format(rv$times[transition_idx], "%Y-%m-%d %H:%M:%S", tz = "UTC"),
      new_state = rv$labels[transition_idx],
      stringsAsFactors = FALSE
    )

    totals <- aggregate(minutes ~ state, rv$intervals, sum, na.rm = TRUE)
    names(totals) <- c("state", "minutes")
    totals$minutes <- round(totals$minutes, 2)
    total_minutes <- sum(totals$minutes, na.rm = TRUE)
    totals$percent <- if (total_minutes > 0) {
      round(100 * totals$minutes / total_minutes, 1)
    } else {
      NA_real_
    }

    write.csv(
      intervals,
      file.path(rv$results_dir, paste0("intervals_", stamp, ".csv")),
      row.names = FALSE,
      na = ""
    )
    write.csv(
      markers,
      file.path(rv$results_dir, paste0("markers_", stamp, ".csv")),
      row.names = FALSE,
      na = ""
    )
    write.csv(
      totals,
      file.path(rv$results_dir, paste0("totals_", stamp, ".csv")),
      row.names = FALSE,
      na = ""
    )

    rv$saved <- TRUE
  }

  observeEvent(input$finish, {
    rv$playing <- FALSE
    save_results()
    showNotification(
      paste("Results saved in", rv$results_dir),
      type = "message",
      duration = 10
    )
  })

  output$download_intervals <- downloadHandler(
    filename = function() {
      paste0("autographer_intervals_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      calculate_results()
      x <- rv$intervals
      x$start_time <- format(x$start_time, "%Y-%m-%d %H:%M:%S", tz = "UTC")
      x$end_time <- format(x$end_time, "%Y-%m-%d %H:%M:%S", tz = "UTC")
      write.csv(x, file, row.names = FALSE, na = "")
    }
  )

  output$viewer <- renderUI({
    if (length(rv$files) == 0L) {
      return(
        div(
          class = "viewer-card",
          h3(style = "color:white;", "Open any JPG from the Autographer folder.")
        )
      )
    }

    img_url <- session$fileUrl(
      paste0("autographer_", rv$index, ".jpg"),
      rv$files[rv$index],
      contentType = "image/jpeg"
    )

    image_state <- rv$labels[rv$index]

    state_class <- if (identical(image_state, "Outdoors")) {
      "state-banner outdoors"
    } else {
      "state-banner indoors"
    }

    div(
      class = "viewer-card",
      tags$img(src = img_url),
      div(class = state_class, toupper(image_state)),
      div(
        class = "image-info",
        paste0(
          "Image ", rv$index, " / ", length(rv$files),
          " | ", basename(rv$files[rv$index]),
          " | ", format(rv$times[rv$index], "%Y-%m-%d %H:%M:%S", tz = "UTC"),
          " UTC | ", if (rv$playing) "PLAYING" else "PAUSED"
        )
      )
    )
  })

  output$progress_ui <- renderUI({
    if (length(rv$files) == 0L) return(NULL)

    pct <- round(100 * rv$index / length(rv$files), 1)

    tagList(
      div(
        class = "progress",
        div(
          class = "progress-bar",
          role = "progressbar",
          style = paste0("width:", pct, "%;"),
          paste0(pct, "%")
        )
      )
    )
  })

  output$status_box <- renderUI({
    if (length(rv$files) == 0L) {
      return(div(class = "status-box", "No images loaded."))
    }

    div(
      class = "status-box",
      HTML(paste0(
        "<b>Folder:</b> ", rv$folder, "<br>",
        "<b>Current image:</b> ", rv$labels[rv$index], "<br>",
        "<b>Active mode:</b> ", rv$active_state, "<br>",
        "<b>Image:</b> ", rv$index, " / ", length(rv$files), "<br>",
        "<b>Saved:</b> ", if (rv$saved) "Yes" else "No"
      ))
    )
  })

  output$event_log <- renderTable({
    req(length(rv$files) > 0L)

    transition_idx <- c(1L, which(rv$labels[-1L] != rv$labels[-length(rv$labels)]) + 1L)
    x <- data.frame(
      Time = format(rv$times[transition_idx], "%H:%M:%S", tz = "UTC"),
      State = rv$labels[transition_idx],
      Image = transition_idx,
      check.names = FALSE
    )
    x[nrow(x):1, , drop = FALSE]
  }, striped = TRUE, bordered = FALSE, spacing = "xs")

  output$marker_table <- renderTable({
    req(length(rv$files) > 0L)

    transition_idx <- c(1L, which(rv$labels[-1L] != rv$labels[-length(rv$labels)]) + 1L)

    data.frame(
      Marker = seq_along(transition_idx),
      Image = transition_idx,
      Time = format(rv$times[transition_idx], "%Y-%m-%d %H:%M:%S", tz = "UTC"),
      State = rv$labels[transition_idx],
      File = basename(rv$files[transition_idx]),
      check.names = FALSE
    )
  }, striped = TRUE, bordered = TRUE, spacing = "s")

  output$interval_table <- renderTable({
    if (length(rv$files) == 0L) {
      return(data.frame(Message = "No images loaded."))
    }

    calculate_results()

    data.frame(
      Interval = rv$intervals$interval_id,
      State = rv$intervals$state,
      Start = format(rv$intervals$start_time, "%Y-%m-%d %H:%M:%S", tz = "UTC"),
      End = format(rv$intervals$end_time, "%Y-%m-%d %H:%M:%S", tz = "UTC"),
      Minutes = round(rv$intervals$minutes, 2),
      check.names = FALSE
    )
  }, striped = TRUE, bordered = TRUE, spacing = "s")

  output$totals_table <- renderTable({
    if (length(rv$files) == 0L) {
      return(data.frame(Message = "No images loaded."))
    }

    calculate_results()

    totals <- aggregate(minutes ~ state, rv$intervals, sum, na.rm = TRUE)
    names(totals) <- c("State", "Minutes")
    totals$Minutes <- round(totals$Minutes, 2)
    total <- sum(totals$Minutes, na.rm = TRUE)
    totals$Percent <- if (total > 0) round(100 * totals$Minutes / total, 1) else NA_real_

    totals
  }, striped = TRUE, bordered = TRUE, spacing = "s")

  observeEvent(input$archive_images, {
    req(length(rv$files) > 0L)

    if (!rv$saved) {
      showNotification("Finish the review and save results before archiving.", type = "error")
      return()
    }

    showModal(
      modalDialog(
        title = "Archive all images?",
        p("The JPG files will be moved into an Archived subfolder."),
        footer = tagList(
          modalButton("Cancel"),
          actionButton("confirm_archive", "Archive images", class = "btn-info")
        ),
        easyClose = FALSE
      )
    )
  })

  observeEvent(input$confirm_archive, {
    archive_dir <- file.path(rv$folder, "Archived")
    dir.create(archive_dir, recursive = TRUE, showWarnings = FALSE)

    destination <- file.path(archive_dir, basename(rv$files))
    ok <- file.rename(rv$files, destination)

    removeModal()

    if (all(ok)) {
      showNotification(
        paste(length(rv$files), "images moved to", archive_dir),
        type = "message",
        duration = 10
      )
      rv$files <- character()
      rv$times <- as.POSIXct(character())
      rv$index <- 1L
      rv$playing <- FALSE
    } else {
      showNotification(
        "Some images could not be archived. They may be open in another program.",
        type = "error",
        duration = NULL
      )
    }
  })

  observeEvent(input$delete_images, {
    req(length(rv$files) > 0L)

    if (!rv$saved) {
      showNotification("Finish the review and save results before deleting.", type = "error")
      return()
    }

    showModal(
      modalDialog(
        title = "Permanently delete all images?",
        p("This action cannot be undone."),
        textInput("delete_text", "Type DELETE to confirm"),
        footer = tagList(
          modalButton("Cancel"),
          actionButton("confirm_delete", "Delete permanently", class = "btn-danger")
        ),
        easyClose = FALSE
      )
    )
  })

  observeEvent(input$confirm_delete, {
    if (!identical(trimws(input$delete_text), "DELETE")) {
      showNotification("Type DELETE exactly.", type = "error")
      return()
    }

    files_to_delete <- rv$files[file.exists(rv$files)]
    ok <- file.remove(files_to_delete)
    removeModal()

    if (all(ok)) {
      showNotification(
        paste(length(files_to_delete), "images permanently deleted."),
        type = "warning",
        duration = 10
      )
      rv$files <- character()
      rv$times <- as.POSIXct(character())
      rv$index <- 1L
      rv$playing <- FALSE
    } else {
      showNotification(
        "Some images could not be deleted.",
        type = "error",
        duration = NULL
      )
    }
  })

  observeEvent(input$exit_app, {
    rv$playing <- FALSE
    stopApp()
  })
}

shinyApp(ui, server)
